const outPath = path.join(__dirname, '..', 'frontend', 'config', 'guide-content', 'it', 'create-worksheet-bundles.ts');
fs.writeFileSync(outPath, content, 'utf8');
console.log('Written:', outPath);

// Verify no \\uXXXX escapes
const written = fs.readFileSync(outPath, 'utf8');
const escapes = written.match(/\\u[0-9a-fA-F]{4}/g);
if (escapes) {
  console.error('ERROR: Found \\uXXXX escapes:', [...new Set(escapes)]);
  process.exit(1);
} else {
  console.log('OK: No \\uXXXX escapes found');
}

// Check titleTag length
const titleMatch = written.match(/titleTag:\s*'([^']+)'/);
if (titleMatch) {
  console.log(`titleTag (${titleMatch[1].length} chars): ${titleMatch[1]}`);
  if (titleMatch[1].length > 60) console.error('ERROR: titleTag > 60 chars!');
}

// Check metaDescription length
const metaMatch = written.match(/metaDescription:\s*'([^']+)'/);
if (metaMatch) {
  console.log(`metaDescription (${metaMatch[1].length} chars): ${metaMatch[1]}`);
  if (metaMatch[1].length < 150 || metaMatch[1].length > 160) console.error('ERROR: metaDescription not 150-160 chars!');
}
